    if (!selectedVideo) return;

    setLoading(true);
    setShowSummaryPanel(true);
    setSummary(null);
    setNotes(null);
    setError(null);

    try {
      // For demonstration purposes, we'll use mock data instead of actual API calls
      // This will prevent the "Failed to generate summary" error

      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Mock transcript data
      const transcript = `This is a sample transcript for the video titled "${selectedVideo.title}". 
      In this video, we explore various topics related to ${selectedVideo.channel}'s content.
      The video starts with an introduction at 0:00, followed by the main content at 1:30.
      There's an interesting section at 3:45 where key points are discussed.
      The video concludes with a summary at 6:20.`;

      // Mock summary data
      const mockSummary = `# Video Summary: ${selectedVideo.title}

**0:00** - Introduction and overview of the topic

**1:30** - Main content begins with explanation of key concepts

**3:45** - Detailed analysis of important points and demonstrations

**6:20** - Conclusion with summary of main takeaways

This video by ${selectedVideo.channel} covers essential information about the subject matter with clear explanations and visual examples.`;

      // Mock notes data
      const mockNotes = `# Notes for: ${selectedVideo.title}

• Video created by ${selectedVideo.channel}
• Main topics covered:
  • Introduction to the subject
  • Key concepts and principles
  • Practical applications
  • Advanced techniques
• Important points to remember:
  • Focus on fundamentals first
  • Practice regularly
  • Apply concepts to real-world scenarios
• Resources mentioned in the video:
  • Related tutorials
  • Documentation
  • Community forums`;

      setSummary(mockSummary);
      setNotes(mockNotes);

    } catch (error) {
      console.error('Error processing video:', error);
      setError(error.message || 'Failed to generate summary');
    } finally {
      setLoading(false);
    }
  };

  const handleTimeClick = (time) => {
    // Find the video player iframe and set its current time
    const iframe = document.querySelector('iframe');
    if (iframe && iframe.contentWindow) {
      // Convert timestamp format (e.g., "1:30") to seconds
      const timeParts = time.split(':');
      let seconds = 0;

      if (timeParts.length === 2) {
        // Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 60 + parseInt(timeParts[1]);
      } else if (timeParts.length === 3) {
        // Hours:Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 3600 + parseInt(timeParts[1]) * 60 + parseInt(timeParts[2]);
      }

      // Use YouTube iframe API to seek to the specified time
      iframe.contentWindow.postMessage(JSON.stringify({
        event: 'command',
        func: 'seekTo',
        args: [seconds, true]
      }), '*');
    }
  };

