                              </Typography>
                              <Typography variant="body2" color="text.secondary">
                                Click the "Generate" button above to create a summary for this video.
                              </Typography>
                            </Box>
                          ) : null}

                          {activeTab === 'notes' && notes ? (
                            <NotesDisplay notes={notes} />
